    # Backslash escapes ASCII punctuation only, never a line ending or arbitrary text.
    return (
        line[i] == "\\"
        and i + 1 < len(line)
        and "!" <= (escaped := line[i + 1]) <= "~"
        and not escaped.isalnum()
    )


