def _link_destination_end(line: str) -> int | None:
    angle = line.startswith("<")
    depth = 0
    i = int(angle)
    while i < len(line):
        char = line[i]
        if _link_escape_at(line, i):
            i += 2
            continue
        if angle:
            if char == ">":
                return i + 1
            if char == "<":
                return None
        elif char == " ":
            break
        elif ord(char) < 32 or ord(char) == 127:
            return None
        elif char == "(":
            depth += 1
        elif char == ")":
            if not depth:
                return None
            depth -= 1
        i += 1
    return i if i and not angle and not depth else None


